window.addEventListener("orientationchange", onOrientationChange);

function onOrientationChange() {
    if (window.matchMedia("(orientation: portrait)").matches) {
        sizeHandler()
    }
    if (window.matchMedia("(orientation: landscape)").matches) {
        sizeHandler()
    }
}

function sizeHandler() {
    window.scrollTo(0, 1);
    if (!$("#canvas")) {
        return
    }
    var e = CANVAS_WIDTH;
    var t = CANVAS_HEIGHT;
    var i = window.innerWidth;
    var n = window.innerHeight;
    multiplier = Math.min(n / t, i / e);
    var r = e * multiplier;
    var a = t * multiplier;
    $("#canvas").css("width", r + "px");
    $("#canvas").css("height", a + "px");
    $("#canvas").css("left", i / 2 - r / 2 + "px")
}

function randomFloatBetween(e, t, i) {
    if (typeof i === "undefined") {
        i = 2
    }
    return parseFloat(Math.min(e + Math.random() * (t - e), t).toFixed(i))
}

function shuffle(e) {
    var t = e.length,
        i, n;
    while (0 !== t) {
        n = Math.floor(Math.random() * t);
        t -= 1;
        i = e[t];
        e[t] = e[n];
        e[n] = i
    }
    return e
}

function formatTime(e) {
    e /= 1e3;
    var t = Math.floor(e / 60);
    var i = e - t * 60;
    i = parseFloat(i).toFixed(1);
    var n = "";
    if (t < 10) {
        n += "0" + t + ":"
    } else {
        n += t + ":"
    } if (i < 10) {
        n += "0" + i
    } else {
        n += i
    }
    return n
}

function NoClickDelay(e) {
    this.element = e;
    if (window.Touch) this.element.addEventListener("touchstart", this, false)
}
NoClickDelay.prototype = {
    handleEvent: function(e) {
        switch (e.type) {
            case "touchstart":
                this.onTouchStart(e);
                break;
            case "touchmove":
                this.onTouchMove(e);
                break;
            case "touchend":
                this.onTouchEnd(e);
                break
        }
    },
    onTouchStart: function(e) {
        e.preventDefault();
        this.moved = false;
        this.element.addEventListener("touchmove", this, false);
        this.element.addEventListener("touchend", this, false)
    },
    onTouchMove: function(e) {
        this.moved = true
    },
    onTouchEnd: function(e) {
        this.element.removeEventListener("touchmove", this, false);
        this.element.removeEventListener("touchend", this, false);
        if (!this.moved) {
            var t = document.elementFromPoint(e.changedTouches[0].clientX, e.changedTouches[0].clientY);
            if (t.nodeType === 3) t = t.parentNode;
            var i = document.createEvent("MouseEvents");
            i.initEvent("click", true, true);
            t.dispatchEvent(i)
        }
    }
};

